insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('jmh','정명희','Jeong Myeong hee','원로작가','한국화','{}'::text[],array['수묵담채','금강 연작','족보 시리즈']::text[],1945,'충남 홍성','대전',null,'1970년대 족보 시리즈에서 금강 연작까지','충남 홍성에서 태어나 홍익대와 중앙대 예술대학원에서 수학했다. 1975년 대전 홍명미술관에서 첫 개인전을 연 뒤 대전을 중심으로 활동하며, 금강을 주제로 한 연작(금강 사계송, 대하 금강, 금강사랑)을 이어 왔다. 1970년대 족보 시리즈, 1990년대 백두산·중국·히말라야 기행 작업도 남겼다. 화문집과 시집을 펴낸 시인이기도 하다.','[["現","선화기독교미술관장"],["1996","미술의 해 대전광역시 조직위원장"],["1993","대전광역시 문화상 수상"],["1990","대한민국미술대전 심사위원"],["1989","안견 미술상 수상"],["1971–82","백양회·중앙미술대전·충남도전 특선 및 대상"]]'::jsonb,'[["2000","환경, 생명의 조형언어","공평화랑·갤러리 사비나(서울), 대전 문화원·현대화랑·창신화랑·오원화랑"],["1998","금강사랑 전국 6대 도시 순회전","서울 갤러리사바나, 대구 신미화랑, 부산 롯데화랑, 전주 갤러리휴먼, 광주 궁동갤러리, 대전 현대화랑"],["1997","다시 금강으로 전","대전 한림미술관, 공주문예회관"],["1996","중국기행전","대전 현대화랑"],["1995","금강에서 장강까지 사생리포트","서울 대림화랑"],["1993","금강사계연작 春夏秋冬전","대전 오원화랑"],["1992","신 금강전","서울 서초갤러리·청작미술관, 대전 오원화랑"],["1991","아! 백두산전","대전 오원화랑, 대구 중앙화랑"],["1989","대하 금강전 / 안견 미술상 수상기념전","서울 갤러리, 대전 문화원"],["1987","아름다운 금강전 / 기산 현대 수묵리전","서울 파르코문화센터, 대전 예가화랑"],["1986","아이러브 금강전","대전 신신화랑"],["1985","금강 사계송전 / 1000리 금강 송전","서울 갤러리, 대전 시민회관·공간사랑"],["1983","기산 정명희전","서울 동덕미술관, 대전 문화원화랑, 청주 청탑화랑"],["1982","정명희전","대전 공간사랑"],["1981","箕山 정명희전","서울 관훈미술관, 대전 시민회관"],["1977","一淸 정명희전","대전 홍명미술관"],["1975","一淸 정명희 작품전","대전 홍명미술관"]]'::jsonb,'국립현대미술관, 대영박물관, 서울시립미술관, 한양대박물관, 대전대박물관, 대전시립미술관, 충청남도, 대전상공회의소, 충청은행, 한국화약 등',array['「하늘을 나르는 물고기」 (화문집)','「백두산에서 히말라야까지」 (화문집)','「하늘그림자」 (시집)','「아침이 숲을 깨운다」 (시집)','「아메리카를 포기한다」 (시집)','「금강사랑-고백 혹은 변명」 (시집)']::text[],'{"name":"한국예술디지털아카이브(DA-Arts) 미술작가 500人","url":"https://www.daarts.or.kr/visual/artist"}'::jsonb,512,'ink',array['#ECE8DF','#1C1C1C','#6B6A64','#8A3B2E','#C9C2B3']::text[],true,false,10);
