insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('ysg','윤석규',null,'원로작가','서양화','{}'::text[],array['비구상']::text[],1946,null,'서울','오십 년을 그렸는데도 붓을 들 때마다 처음 같아요.',null,'1970년대 단색 추상에서 출발해, 흙빛 색면을 겹쳐 시간이 쌓인 땅을 그려왔다. 여든을 넘긴 지금도 매일 아침 작업실에 나간다.','[["1970","서울대학교 회화과 졸업"],["2025","회고전 「땅의 연대기」, 시립미술관"],["2010","대한민국예술원 회원"],["1988","서울올림픽 기념 국제현대미술전 참여"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'bands',array['#E6DFD2','#7A2E22','#C98B3F','#2F2A24','#B8AE9C']::text[],false,false,20);
