insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('sjw','송재원',null,'원로작가','서예·문인화','{}'::text[],array['한글서예','전각']::text[],1943,null,'충남 공주','획 하나에 하루를 다 써도 아깝지 않아요.',null,'궁체와 판본체를 바탕으로 현대 한글서예의 조형을 탐구해 왔다. 직접 새긴 전각을 작품마다 찍어 완성한다.','[["1966","공주교육대학 졸업"],["2023","초대전 「획의 시간」, 서예박물관"],["2008","대한민국서예대전 초대작가"],["1995","개인전 「훈민정음 해례」"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'brush',array['#F1EBDD','#141414','#3B3B3B','#B0322A','#D9D0BE']::text[],false,false,30);
