insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('cjs','최정숙',null,'원로작가','한국화','{}'::text[],array['진경·실경산수','수묵화']::text[],1951,null,'경북 경주','산은 그대로인데 제 눈이 달라져요. 그걸 그리는 거예요.',null,'경주 남산을 사십 년 넘게 오르내리며 그린 실경산수로 알려졌다. 최근에는 먹과 쪽빛만으로 산의 윤곽을 줄여 나가고 있다.','[["1974","이화여자대학교 동양화과 졸업"],["2024","초대전 「남산 사십 년」"],["2015","올해의 한국화가상"],["1992","개인전 「경주 실경」"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'ink',array['#EFEADF','#23262B','#5E6B5A','#2F5D8A','#BDB6A6']::text[],false,false,40);
