insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('mjh','문재혁',null,'중견작가','조각',array['설치·복합매체']::text[],array['추상조각','설치']::text[],1979,null,'경기 파주','재료가 먼저 무게를 말해요. 저는 들어주는 쪽이죠.',null,'폐목재와 콘크리트 블록을 쌓아 균형이 무너지기 직전의 상태를 만든다. 작품은 매 전시마다 공간에 맞춰 다시 쌓는다.','[["2006","서울대학교 조소과 졸업"],["2026","개인전 「무게의 문법」, 스페이스 결"],["2022","레지던시 입주, 파주 작업실 7"],["2020","공공미술 「쉼의 기둥」 설치"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'blocks',array['#E8E2D8','#6B4A33','#B98B5E','#2E2A26','#C9C1B4']::text[],false,false,50);
