insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('oeb','오은비',null,'중견작가','공예·도예','{}'::text[],array['도자','백자']::text[],1981,null,'경기 이천','가마 문을 열 때까지는 제 작품이 아니에요. 불이 마지막 손을 대거든요.',null,'달항아리의 비대칭을 현대적인 비례로 다시 빚는다. 청회색 유약이 흘러내린 자국을 그대로 남긴다.','[["2005","서울과학기술대학교 도예학과 졸업"],["2025","개인전 「흘러내린 자리」"],["2022","공예트렌드페어 올해의 작가"],["2019","이천 도예 레지던시"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'vessel',array['#E9E6DF','#F7F5EF','#9FB3B5','#5D6F73','#C7B99E']::text[],false,false,60);
