insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('pjo','박준오',null,'중견작가','판화','{}'::text[],array['목판']::text[],1983,null,'전북 전주','찍는 건 한 번이지만, 새기는 건 몇 주가 걸려요.',null,'목판에 격자를 새기고 한 판을 여러 색으로 겹쳐 찍는다. 찍힐 때마다 조금씩 어긋나는 자리가 작업의 중심이다.','[["2009","전북대학교 미술학과 졸업"],["2026","개인전 「찍힌 자리」, 서학동 갤러리"],["2024","도록 『찍힌 자리』 발간"],["2019","국제판화비엔날레 참여"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'grid',array['#EDE7DA','#1F3B2D','#C4553A','#2A2A2A','#D8B86A']::text[],false,false,70);
