insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('jmr','정미래',null,'중견작가','한국화','{}'::text[],array['수묵화']::text[],1985,null,'대구','먹은 기다려야 번져요. 조급하면 그림이 먼저 알아요.',null,'한지에 먹을 여러 번 스며들게 해 호흡의 리듬을 화면에 남긴다. 붉은 인주색을 한 점씩 더해 시선이 머물 자리를 만든다.','[["2010","계명대학교 동양화과 졸업"],["2026","개인전 「먹의 호흡」, 봉산문화회관"],["2023","대한민국 한국화 대전 특선"],["2021","개인전 「번짐」"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'ink',array['#F3EFE6','#1A1A1A','#6E6A62','#A63A2B','#C8C2B6']::text[],false,false,80);
