insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('hsy','한서윤',null,'청년작가','서양화','{}'::text[],array['구상']::text[],1988,null,'서울','수평선은 제가 매일 다시 긋는 약속이에요.',null,'바다와 하늘이 맞닿는 선을 반복해서 그리며, 같은 풍경이 날마다 달라지는 순간을 기록한다. 얇은 유화 물감을 스무 겹 이상 쌓아 빛이 층 사이에 머물게 한다.','[["2013","홍익대학교 회화과 졸업"],["2026","개인전 「수평의 시간」, 갤러리 소향"],["2024","개인전 「물때」, 공간 여백"],["2023","제12회 신진작가상"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'bands',array['#DCE3E8','#274A6B','#8FA7B8','#E9D9C4','#1B2733']::text[],false,false,90);
