insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('ldh','이도하',null,'청년작가','사진','{}'::text[],array['파인아트']::text[],1991,null,'서울','밤에는 빛이 입자처럼 보여요. 그걸 붙잡으려고 셔터를 오래 열어둬요.',null,'도시의 새벽 세 시를 장노출로 기록한다. 필름을 직접 현상하며 입자가 거칠게 남는 쪽을 택한다.','[["2016","중앙대학교 사진학과 졸업"],["2026","개인전 「밤의 입자」, 사진공간 한"],["2024","그룹전 「도시의 온도」"],["2022","사진집 『새벽 세 시』 출간"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'grain',array['#0E1424','#3A4A7A','#D98A5B','#F2C9A0','#6B2F3A']::text[],false,false,100);
