insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('knr','김나린',null,'청년작가','뉴미디어',array['설치·복합매체']::text[],array['인터랙티브','영상']::text[],1994,null,'광주','꺼진 화면도 하나의 장면이에요. 신호가 없을 때 가장 많이 보여요.',null,'방송이 끝난 뒤의 노이즈 화면과 신호 오류를 재료로 영상과 설치를 만든다. 관객의 움직임에 따라 화면이 흐트러지는 인터랙티브 작업을 한다.','[["2019","한국예술종합학교 미술원 졸업"],["2026","개인전 「신호 없는 채널」, 빛고을 미디어랩"],["2025","미디어아트 창작 지원 선정"],["2023","그룹전 「화면 밖」"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'neon',array['#07080C','#FF4D8D','#38E1FF','#B6FF5C','#6A5CFF']::text[],false,false,110);
