insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,works_total,style,pal,is_real,hidden,sort) values ('rhj','류하진',null,'청년작가','드로잉·일러스트','{}'::text[],array['드로잉']::text[],1996,null,'부산','연필이 멈추는 곳까지가 그날의 그림이에요.',null,'동네 골목을 걸으며 연필과 목탄으로 하루 한 장씩 그린다. 지운 자국도 지우지 않고 화면에 남긴다.','[["2020","부산대학교 미술학과 졸업"],["2025","개인전 「하루 한 장」"],["2024","청년 드로잉 공모 선정"],["2023","그림책 『골목의 오후』 출간"]]'::jsonb,'[]'::jsonb,null,'{}'::text[],null,null,'lines',array['#F4F2EC','#2A2A2E','#6D6D75','#D2553F','#BFC6CC']::text[],false,false,120);
