insert into public.interviews (artist_id,title,date,lead,qa) values ('hsy','매일 다시 긋는 수평선','2026.09.20','「수평의 시간」 개인전을 앞두고 작업실에서 만났다. 벽에는 같은 수평선을 그린 캔버스 스무 점이 나란히 걸려 있었다.','[["왜 수평선만 그리나요?","수평선은 늘 같은 자리에 있는 것 같지만 날마다 색이 달라요. 같은 걸 계속 그려야 그 차이가 보여요."],["물감을 스무 겹 넘게 올린다고요.","한 겹이 마르는 데 사흘쯤 걸려요. 그래서 한 작품에 두 달 가까이 걸리죠. 빛이 층 사이에 들어가 머무는 느낌을 원해서요."],["이번 전시에서 봐줬으면 하는 게 있다면요?","작품 앞에서 조금 오래 서 계셔 보세요. 가까이 가면 선이 흐려지고, 멀어지면 다시 선명해져요."]]'::jsonb);
insert into public.interviews (artist_id,title,date,lead,qa) values ('sjw','획 하나에 하루를 쓰다','2026.09.08','예순 해 가까이 한글 획을 다듬어 온 송재원을 공주 작업실에서 만났다.','[["요즘도 매일 쓰시나요?","아침에 먹을 가는 데만 한 시간이 걸려요. 그 시간이 제일 좋아요."]]'::jsonb);
insert into public.interviews (artist_id,title,date,lead,qa) values ('mjh','재료가 먼저 무게를 말한다','2026.09.02','문재혁은 전시마다 작품을 다시 쌓는다. 같은 작품이 공간에 따라 다른 모양이 된다.','[["작품이 매번 달라지면 어느 게 원본인가요?","쌓는 규칙이 원본이에요. 결과는 그 공간에서만 가능한 한 번이고요."]]'::jsonb);
insert into public.interviews (artist_id,title,date,lead,qa) values ('knr','꺼진 화면도 하나의 장면이다','2026.08.18','방송이 끝난 뒤 남는 노이즈 화면에서 출발한 김나린의 작업을 이야기했다.','[["노이즈에 끌린 계기가 있나요?","어릴 때 새벽에 TV가 켜진 채로 잠들곤 했어요. 깨어나면 늘 그 화면이 있었죠."]]'::jsonb);
