insert into public.notices (tag,title,body,date) values ('안내','arttan 주소는 www.arttan.co.kr 이에요','art(미술)와 灘(여울 탄)을 합친 이름이에요.','2026.09.28');
insert into public.notices (tag,title,body,date) values ('업데이트','정명희 작가 아카이브를 열었어요','한국예술디지털아카이브(DA-Arts) 미술작가 500人 자료를 바탕으로 작품 11점과 개인전 17건을 정리했어요.','2026.09.28');
insert into public.notices (tag,title,body,date) values ('안내','작가 등록 신청은 이렇게 해요','위쪽의 ''작가 등록'' 버튼으로 신청하면 운영팀이 확인한 뒤 승인해요. 분류(원로·중견·청년)는 나이를 기준으로 정하고, 필요하면 조정해요.','2026.09.29');
insert into public.notices (tag,title,body,date) values ('공지','arttan 홈페이지 초안을 공개했어요','작가 포트폴리오, 인터뷰, 도록, 갤러리, 전시일정을 한곳에서 보는 arttan의 첫 초안이에요. 정명희 작가 외의 작가·전시 정보는 예시예요.','2026.09.30');
